import{_ as e,c as i,o as r,aj as a}from"./chunks/framework.e3UxQEvm.js";const m=JSON.parse('{"title":"Get a Solid Pod","description":"","frontmatter":{},"headers":[],"relativePath":"solid-pod.md","filePath":"solid-pod.md"}'),t={name:"solid-pod.md"};function d(l,o,s,n,p,h){return r(),i("div",null,[...o[0]||(o[0]=[a('<h1 id="get-a-solid-pod" tabindex="-1">Get a Solid Pod <a class="header-anchor" href="#get-a-solid-pod" aria-label="Permalink to “Get a Solid Pod”">​</a></h1><p>Solid Pod is where your SolidCouch data are stored. You can register with a Pod provider, or host your own.</p><h2 id="get-a-pod-from-a-solid-pod-provider" tabindex="-1">Get a Pod from a Solid Pod provider <a class="header-anchor" href="#get-a-pod-from-a-solid-pod-provider" aria-label="Permalink to “Get a Pod from a Solid Pod provider”">​</a></h2><p>There are various <a href="https://solidproject.org/get_a_pod" target="_blank" rel="noreferrer">Solid Pod providers</a> you can choose from. However, not all providers are currently compatible with SolidCouch.</p><p>You can go to your <a href="./instances">SolidCouch instance</a>, click <code>Sign in</code> &gt; <code>Don&#39;t have a Solid Pod yet?</code>, and select one of the options.</p><h2 id="host-your-webid-on-your-domain" tabindex="-1">Host your WebId on your domain <a class="header-anchor" href="#host-your-webid-on-your-domain" aria-label="Permalink to “Host your WebId on your domain”">​</a></h2><p>If you own a <strong>domain name</strong>, you can have your <a href="https://solidproject.org/TR/protocol#webid" target="_blank" rel="noreferrer">WebID</a> on your domain. This gives you more control over your Solid identity.</p><p>Choose the option <em>&quot;Use my existing WebID to access my Pod&quot;</em> with one of these providers:</p><ul><li>solidcommunity.net</li><li>solidweb.me</li><li>solid.redpencil.io</li><li>teamid.live</li><li>pods.solidcommunity.au</li></ul><p>To complete the process, you must prove that the WebID on your domain belongs to you. Afterwards, the WebID must point to your Profile Document.</p><p>This section needs more explanation.</p><h2 id="host-your-solid-pod" tabindex="-1">Host your Solid Pod <a class="header-anchor" href="#host-your-solid-pod" aria-label="Permalink to “Host your Solid Pod”">​</a></h2><p>You can also <strong>host your Pod</strong>. This will give you full control over your data. However, it&#39;s more complicated to set up, and requires maintenance. We recommend <a href="https://github.com/communitysolidserver/communitysolidserver#-running-the-server" target="_blank" rel="noreferrer">Community Solid Server</a>.</p><p>This section needs more explanation.</p><h2 id="compatibility-with-solidcouch" tabindex="-1">Compatibility with SolidCouch <a class="header-anchor" href="#compatibility-with-solidcouch" aria-label="Permalink to “Compatibility with SolidCouch”">​</a></h2><h3 id="compatible-solid-pod-providers" tabindex="-1">Compatible Solid Pod providers <a class="header-anchor" href="#compatible-solid-pod-providers" aria-label="Permalink to “Compatible Solid Pod providers”">​</a></h3><h3 id="compatible-solid-server-implementations" tabindex="-1">Compatible Solid server implementations <a class="header-anchor" href="#compatible-solid-server-implementations" aria-label="Permalink to “Compatible Solid server implementations”">​</a></h3><p>The following Solid servers are known to work well with SolidCouch.</p><ul><li>Community Solid Server</li><li>Pivot</li><li>Node Solid Server</li></ul>',19)])])}const u=e(t,[["render",d]]);export{m as __pageData,u as default};
